th knobs for reset, init, valid and boundary-byte probabilities, and fails itself on coverage shortfalls. It prints one NIRMAAN-SIM verdict line and then calls $finish. A watchdog prevents a hang without printing a second verdict.", "entry": "tb_crc8_block"}], "tool_runs": [], "claims": ["The testbench has not been simulated by me. Whether it passes on the approved RTL is for the platform's simulator.run to establish.", "The name of the nonce plusarg is not stated in the material I was given. The testbench tries +nonce=, +NONCE=, +nirmaan_nonce= and +NIRMAAN_NONCE=. If the platform uses another name, the verdict will carry no nonce and the gate will fail the run.", "The coverage goal thresholds were sized from expected counts for the fixed seeds, without running them. They are expected, not shown, to be met on the approved RTL.", "Mutants the checks are designed to catch include: init priority below valid, an asynchronous or missing reset, no final inversion, a wrong polynomial, reversed byte order, and an update while valid is low. None of these mutants has been run."], "escalation": null, "notes": "Plain Verilog-2001 is used for Icarus and Verilator --binary compatibility. The random generator is defined in the testbench itself, so a seed repeats on either simulator. Each nonce byte is printed with %c and NUL bytes are skipped, so the verdict line carries no padding. Seeds are printed to the log for replay. Independent review is still required after the platform's simulation run."}

=== FILE: tb_crc8_block.v ===
// Self-checking constrained-random testbench for crc8_block.
// Expected values come from interface_spec.md (reference model and
// hand-computed known answers), never from the RTL's own output.
`timescale 1ns / 1ps
module tb_crc8_block;
    // ---------------- knobs and coverage goals ----------------
    localparam integer ITEMS_PER_PHASE = 3000;
    localparam integer N_SEEDS         = 4;
    localparam integer NEED_TAKEN      = 15000; // bytes taken
    localparam integer NEED_INIT_VALID = 100;   // init and valid on the same edge
    localparam integer NEED_INIT_MID   = 100;   // reload in the middle of a frame
    localparam integer NEED_RST_MID    = 50;    // reset in the middle of a frame
    localparam integer NEED_RST_COINC  = 50;    // reset with init or valid high
    localparam integer NEED_HOLD       = 500;   // valid low, init low
    localparam integer NEED_HOLD_MID   = 200;   // hold inside a frame
    localparam integer NEED_LONG       = 40;    // frames reaching 16 bytes
    localparam integer NEED_EMPTY      = 200;   // crc==00 right after reset/reload
    localparam integer NEED_B00        = 20;    // byte 0x00 taken
    localparam integer NEED_BFF        = 20;    // byte 0xFF taken
    localparam integer NEED_CRC_VALUES = 256;   // distinct crc values seen

    reg        clk   = 1'b0;
    reg        rst_n = 1'b0;
    reg        init  = 1'b0;
    reg        valid = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire [7:0] crc;

    crc8_block dut (
        .clk(clk), .rst_n(rst_n), .init(init),
        .valid(valid), .data(data), .crc(crc)
    );

    always #5 clk = ~clk;

    // ---------------- bookkeeping ----------------
    integer n_pass, n_fail, n_shown, cycle;
    integer n_taken, n_init_valid, n_init_mid, n_rst_mid, n_rst_coinc;
    integer n_hold, n_hold_mid, n_long, n_empty, n_b00, n_bff;
    integer frame_len;
    reg [255:0] seen;
    reg  [7:0] m_run;      // reference running value
    reg        m_known;
    reg [31:0] rng;
    reg [31:0] cur_seed;
    reg        done;
    reg [8*256-1:0] nonce_buf;
    reg        have_nonce;

    // ---------------- reference model (from the spec) ----------------
    // Spec 2.2: per bit, from bit 7 to bit 0, XOR the bit into the top bit,
    // shift left, XOR 0x07 if the bit shifted out was 1. With bit 7 first
    // this is the same as XORing the whole byte in, then 8 conditional shifts.
    function [7:0] ref_take(input [7:0] run, input [7:0] b);
        integer k;
        reg [7:0] v;
        begin
            v = run ^ b;
            for (k = 0; k < 8; k = k + 1)
                v = v[7] ? ({v[6:0], 1'b0} ^ 8'h07) : {v[6:0], 1'b0};
            ref_take = v;
        end
    endfunction

    function [31:0] xs32(input [31:0] x);
        reg [31:0] y;
        begin
            y = x ^ (x << 13);
            y = y ^ (y >> 17);
            y = y ^ (y << 5);
            xs32 = y;
        end
    endfunction

    function [31:0] seed_of(input integer k);
        begin
            case (k)
                0: seed_of = 32'h1D0C5EED;
                1: seed_of = 32'hC0FFEE01;
                2: seed_of = 32'h8BADF00D;
                default: seed_of = 32'h00012345;
            endcase
        end
    endfunction

    function [7:0] boundary(input [2:0] i);
        begin
            case (i)
                3'd0: boundary = 8'h00;
                3'd1: boundary = 8'hFF;
                3'd2: boundary = 8'h80;
                3'd3: boundary = 8'h01;
                3'd4: boundary = 8'h7F;
                3'd5: boundary = 8'hFE;
                3'd6: boundary = 8'hAA;
                default: boundary = 8'h55;
            endcase
        end
    endfunction

    // ---------------- checks ----------------
    // kind: 0 = after edge vs model, 1 = before edge vs model, 2 = known answer
    task cmp8(input [7:0] got, input [7:0] exp, input integer kind);
        begin
            if (got === exp)
                n_pass = n_pass + 1;
            else begin
                n_fail = n_fail + 1;
                if (n_shown < 20) begin
                    n_shown = n_shown + 1;
                    $display("TB MISMATCH seed=0x%h cycle=%0d kind=%0d rst_n=%b init=%b valid=%b data=0x%h expected crc=0x%h got 0x%h",
                             cur_seed, cycle, kind, rst_n, init, valid, data, exp, got);
                end
            end
        end
    endtask

    task goal(input integer count, input integer need);
        begin
            if (count >= need) n_pass = n_pass + 1;
            else begin
                n_fail = n_fail + 1;
                $display("TB COVER SHORTFALL count=%0d need=%0d", count, need);
            end
        end
    endtask

    task lit(input [7:0] exp);
        begin
            cmp8(crc, exp, 2);
        end
    endtask

    // One clock: drive at the falling edge, check before and after the rising edge.
    task step(input r, input i, input v, input [7:0] d);
        reg [7:0] nxt;
        begin
            @(negedge clk);
            rst_n = r; init = i; valid = v; data = d;
            #1;
            // CRC-FINAL: crc follows the running value, not the inputs.
            if (m_known) cmp8(crc, m_run ^ 8'hFF, 1);
            // Spec 2.1/2.2 priority: reset, then reload, then byte, else hold.
            if (!r)       nxt = 8'hFF;
            else if (i)   nxt = 8'hFF;
            else if (v)   nxt = ref_take(m_run, d);
            else          nxt = m_run;
            // coverage bookkeeping
            if (!r) begin
                if (frame_len > 0) n_rst_mid = n_rst_mid + 1;
                if (i || v) n_rst_coinc = n_rst_coinc + 1;
                frame_len = 0;
            end else if (i) begin
                if (v) n_init_valid = n_init_valid + 1;
                if (frame_len > 0) n_init_mid = n_init_mid + 1;
                frame_len = 0;
            end else if (v) begin
                n_taken = n_taken + 1;
                frame_len = frame_len + 1;
                if (frame_len == 16) n_long = n_long + 1;
                if (d == 8'h00) n_b00 = n_b00 + 1;
                if (d == 8'hFF) n_bff = n_bff + 1;
            end else begin
                n_hold = n_hold + 1;
                if (frame_len > 0) n_hold_mid = n_hold_mid + 1;
            end
            @(posedge clk);
            #1;
            m_run = nxt;
            m_known = 1'b1;
            cmp8(crc, m_run ^ 8'hFF, 0);
            // CRC-EMPTY, independent of the model: 0x00 right after reset/reload.
            if (!r || i) begin
                cmp8(crc, 8'h00, 2);
                n_empty = n_empty + 1;
            end
            if ((^crc) !== 1'bx) seen[crc] = 1'b1;
            cycle = cycle + 1;
        end
    endtask

    // ---------------- directed scenarios ----------------
    task directed;
        begin
            // CRC-RESET: reset wins over init and valid; held for several edges.
            step(1'b0, 1'b1, 1'b1, 8'hA5); lit(8'h00);
            step(1'b0, 1'b0, 1'b1, 8'h3C); lit(8'h00);
            step(1'b0, 1'b0, 1'b0, 8'h00); lit(8'h00);
            // CRC-EMPTY and CRC-HOLD after reset, data changing with valid low.
            step(1'b1, 1'b0, 1'b0, 8'h5A); lit(8'h00);
            step(1'b1, 1'b0, 1'b0, 8'hFF); lit(8'h00);
            // CRC-POLY / CRC-ORDER known answers, worked by hand from the spec.
            step(1'b1, 1'b0, 1'b1, 8'h00); lit(8'h0C);
            step(1'b1, 1'b1, 1'b0, 8'h00); lit(8'h00);
            step(1'b1, 1'b0, 1'b1, 8'h80); lit(8'h85);
            step(1'b1, 1'b1, 1'b0, 8'h00); lit(8'h00);
            step(1'b1, 1'b0, 1'b1, 8'h01); lit(8'h0B);
            step(1'b1, 1'b1, 1'b0, 8'h00); lit(8'h00);
            step(1'b1, 1'b0, 1'b1, 8'hFF); lit(8'hFF);
            step(1'b1, 1'b0, 1'b1, 8'h00); lit(8'hFF);
            step(1'b1, 1'b0, 1'b1, 8'h01); lit(8'hF8);
            // CRC-HOLD inside a frame.
            step(1'b1, 1'b0, 1'b0, 8'h12); lit(8'hF8);
            step(1'b1, 1'b0, 1'b0, 8'hED); lit(8'hF8);
            // CRC-INIT: reload wins over a byte on the same edge.
            step(1'b1, 1'b1, 1'b1, 8'h5A); lit(8'h00);
            // Reset in the middle of a frame (synchronous).
            step(1'b1, 1'b0, 1'b1, 8'h80); lit(8'h85);
            step(1'b0, 1'b0, 1'b1, 8'h80); lit(8'h00);
            step(1'b1, 1'b0, 1'b1, 8'h80); lit(8'h85);
        end
    endtask

    // ---------------- constrained-random phase ----------------
    // Probabilities are numerators over 256.
    task run_phase(input integer n, input integer p_rst, input integer p_init,
                   input integer p_valid, input integer p_edge);
        integer k;
        reg [31:0] pr, pd;
        reg rv, iv, vv;
        reg [7:0] dv;
        begin
            for (k = 0; k < n; k = k + 1) begin
                rng = xs32(rng); pr = rng;
                rng = xs32(rng); pd = rng;
                rv = (pr[7:0]   < p_rst)   ? 1'b0 : 1'b1;
                iv = (pr[15:8]  < p_init)  ? 1'b1 : 1'b0;
                vv = (pr[23:16] < p_valid) ? 1'b1 : 1'b0;
                if (pr[31:24] < p_edge) dv = boundary(pd[2:0]);
                else                    dv = pd[15:8];
                step(rv, iv, vv, dv);
            end
        end
    endtask

    // ---------------- verdict ----------------
    task finish_run;
        integer k;
        reg [7:0] ch;
        begin
            if (!done) begin
                done = 1'b1;
                $write("NIRMAAN-SIM ");
                for (k = 255; k >= 0; k = k - 1) begin
                    ch = nonce_buf[k*8 +: 8];
                    if (ch != 8'h00) $write("%c", ch);
                end
                $display(" %0d passed, %0d failed", n_pass, n_fail);
                $finish;
            end
        end
    endtask

    integer s, nvals, b;
    initial begin
        n_pass = 0; n_fail = 0; n_shown = 0; cycle = 0;
        n_taken = 0; n_init_valid = 0; n_init_mid = 0; n_rst_mid = 0;
        n_rst_coinc = 0; n_hold = 0; n_hold_mid = 0; n_long = 0;
        n_empty = 0; n_b00 = 0; n_bff = 0; frame_len = 0;
        seen = 256'b0; m_run = 8'hFF; m_known = 1'b0;
        rng = 32'h1; cur_seed = 32'h0; done = 1'b0;
        nonce_buf = 0; have_nonce = 1'b0;

        if ($value$plusargs("nonce=%s", nonce_buf))               have_nonce = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce_buf))          have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce_buf))  have_nonce = 1'b1;
        else if ($value$plusargs("NIRMAAN_NONCE=%s", nonce_buf))  have_nonce = 1'b1;
        if (!have_nonce) begin
            $display("TB ERROR no nonce plusarg found");
            n_fail = n_fail + 1;
        end

        $display("TB directed scenarios");
        directed;

        for (s = 0; s < N_SEEDS; s = s + 1) begin
            cur_seed = seed_of(s);
            rng = cur_seed;
            $display("TB seed %0d = 0x%h", s, cur_seed);
            step(1'b0, rng[0], rng[1], rng[15:8]);
            step(1'b0, rng[2], rng[3], rng[23:16]);
            run_phase(ITEMS_PER_PHASE,  2,  8, 192, 64); // long frames, few reloads
            run_phase(ITEMS_PER_PHASE,  4, 32, 128, 64); // more holds and reloads
            run_phase(ITEMS_PER_PHASE, 16, 64, 224, 96); // stress: coincident events
        end

        nvals = 0;
        for (b = 0; b < 256; b = b + 1)
            if (seen[b]) nvals = nvals + 1;

        $display("TB COVER taken=%0d init_valid=%0d init_mid=%0d rst_mid=%0d rst_coinc=%0d hold=%0d hold_mid=%0d long=%0d empty=%0d b00=%0d bff=%0d crc_values=%0d",
                 n_taken, n_init_valid, n_init_mid, n_rst_mid, n_rst_coinc,
                 n_hold, n_hold_mid, n_long, n_empty, n_b00, n_bff, nvals);
        goal(n_taken,      NEED_TAKEN);
        goal(n_init_valid, NEED_INIT_VALID);
        goal(n_init_mid,   NEED_INIT_MID);
        goal(n_rst_mid,    NEED_RST_MID);
        goal(n_rst_coinc,  NEED_RST_COINC);
        goal(n_hold,       NEED_HOLD);
        goal(n_hold_mid,   NEED_HOLD_MID);
        goal(n_long,       NEED_LONG);
        goal(n_empty,      NEED_EMPTY);
        goal(n_b00,        NEED_B00);
        goal(n_bff,        NEED_BFF);
        goal(nvals,        NEED_CRC_VALUES);

        finish_run;
    end

    // Watchdog: fail rather than hang; finish_run prints the verdict only once.
    initial begin
        #5000000;
        if (!done) begin
            $display("TB ERROR watchdog expired");
            n_fail = n_fail + 1;
            finish_run;
        end
    end
endmodule
=== END FILE ===
